(function () {
"use strict";
var host = document.getElementById("studyContent");
if (!host) return;
function tabOn(attr, fallback) {
var on = document.querySelector(".study-tab.is-on[data-" + attr + "]");
return on ? on.getAttribute("data-" + attr) : fallback;
}
var qs = new URLSearchParams(location.search);
var qLevel = (qs.get("lv") || "").toUpperCase();
var qKind = (qs.get("kind") || "").toLowerCase();
var qShow = (qs.get("show") || "").toLowerCase();
var COVER_KEY = "jlpt.study.cover";
function readCover() {
try { return localStorage.getItem(COVER_KEY) === "1"; }
catch (e) { return false; }
}
function saveCover() {
try { localStorage.setItem(COVER_KEY, state.cover ? "1" : "0"); }
catch (e) { }
}
var state = {
level: /^N[1-5]$/.test(qLevel) ? qLevel : tabOn("level", "N5"),
kind: ["words", "kanji", "grammar"].indexOf(qKind) !== -1
? qKind : tabOn("kind", "words"),
query: "",
show: ["k", "d", "new"].indexOf(qShow) !== -1 ? qShow : "",
cover: readCover()
};
var cache = {};
var marks = {};
function loadMarks() {
marks = {};
if (typeof readKnow !== "function") return;
var items = readKnow().items;
var pre = state.level + "|";
Object.keys(items).forEach(function (id) {
if (id.indexOf(pre) === 0) marks[id.slice(pre.length)] = items[id].s;
});
}
function markCounts() {
var out = { k: 0, d: 0 };
Object.keys(marks).forEach(function (w) {
if (marks[w] === "k" || marks[w] === "d") out[marks[w]] += 1;
});
return out;
}
function esc(s) {
return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
});
}
function key() { return state.kind + ":" + state.level; }
function load() {
if (cache[key()]) { render(); return; }
if (!host.querySelector(".study-row")) {
host.innerHTML =
'<div class="exam-loading"><div class="spinner"></div></div>';
}
var FIELD = { words: "words", grammar: "patterns", kanji: "kanji" };
fetch(SITE_ROOT + "data/" + state.kind + "/" +
state.level.toLowerCase() + ".json",
{ cache: "no-cache" })
.then(function (r) {
if (!r.ok) throw new Error("HTTP " + r.status);
return r.json();
})
.then(function (d) {
cache[key()] = d[FIELD[state.kind]];
render();
})
.catch(function () {
host.innerHTML = '<p class="stats-empty">' + esc(t("study.unavailable")) +
"</p>";
});
}
function matches(row) {
if (state.kind === "words" && state.show) {
var s = marks[row.w] || "";
if (state.show === "new" ? s !== "" : s !== state.show) return false;
}
if (!state.query) return true;
var hay;
if (state.kind === "words") {
hay = [row.w, row.r, row.romaji, row.en];
} else if (state.kind === "kanji") {
hay = [row.k, row.en.join(" "), row.on.join(" "), row.kun.join(" "),
row.ex.map(function (e) { return e.w + " " + e.en; }).join(" ")];
} else {
hay = [row.p, row.en, row.ne, row.ja, row.ex];
}
return hay.join(" ").toLowerCase().indexOf(state.query) !== -1;
}
function marksBar() {
var n = markCounts();
var total = (cache[key()] || []).length;
var fresh = total - n.k - n.d;
function chip(show, label, count) {
return '<button type="button" class="study-filter' +
(state.show === show ? " is-on" : "") + '" data-show="' + show +
'" aria-pressed="' + (state.show === show ? "true" : "false") + '">' +
esc(t(label)) + (count ? "<b>" + count + "</b>" : "") + "</button>";
}
var quiz = "";
if (n.d >= 4) {
var a = document.getElementById("quizLink");
var base = a ? (a.getAttribute("href") || "quiz.html").split("?")[0]
: "quiz.html";
quiz = '<a class="study-marks-quiz" href="' + base + "?level=" +
state.level + '&amp;kind=words&amp;only=learning">' +
esc(t("study.quizThese")) + ' <span aria-hidden="true">\u2192</span></a>';
}
return '<div class="study-marks">' +
'<p class="study-marks-legend">' + esc(t("study.markLegend")) + "</p>" +
'<div class="study-marks-filters" role="group" aria-label="' +
esc(t("study.filterLabel")) + '">' +
chip("", "study.filterAll", 0) +
chip("d", "study.filterLearning", n.d) +
chip("k", "study.filterKnown", n.k) +
chip("new", "study.filterUnmarked", (n.k || n.d) ? fresh : 0) +
quiz +
"</div>" +
"</div>";
}
function countLine(n, noun, withCover) {
var toggle = "";
if (withCover) {
toggle = '<button type="button" class="study-cover"' + coverAttrs() +
">" + esc(coverLabel()) + "</button>";
}
return '<div class="study-count"><span>' + n + " " + esc(t(noun)) +
"</span>" + toggle + "</div>";
}
function coverLabel() {
return t(state.cover ? "study.uncover" : "study.cover");
}
function coverAttrs() {
return state.cover ? "" : ' title="' + esc(t("study.coverHint")) + '"';
}
function applyCover() {
var list = host.querySelector(".study-list");
if (list) {
list.classList.toggle("is-covered", state.cover);
if (state.cover) {
list.querySelectorAll(".study-row.is-shown").forEach(function (r) {
r.classList.remove("is-shown");
});
}
}
var btn = host.querySelector(".study-cover");
if (btn) {
btn.textContent = coverLabel();
if (state.cover) btn.removeAttribute("title");
else btn.setAttribute("title", t("study.coverHint"));
}
}
function render() {
if (state.kind === "words") loadMarks();
var rows = (cache[key()] || []).filter(matches);
var bar = state.kind === "words" ? marksBar() : "";
if (!rows.length) {
var why = state.show && !state.query ? "study.markEmpty" : "exams.noMatch";
var noun = { words: "study.wordsCount", grammar: "study.patternsCount",
kanji: "study.kanjiCount" }[state.kind];
host.innerHTML = countLine(0, noun, false) + bar +
'<p class="stats-empty">' + esc(t(why)) + "</p>";
watchMarks();
return;
}
var HEAD = {
words: ["study.colWord", "study.colReading", "study.colMeaning"],
grammar: ["study.colPattern", "study.colMeaning", "study.colExample"],
kanji: ["study.kanji", "study.colReading", "study.colMeaning"]
};
var cls = { words: "", grammar: " is-grammar", kanji: " is-kanji" };
var head = '<div class="study-row is-head' + cls[state.kind] + '">' +
HEAD[state.kind].map(function (k) {
return "<span>" + esc(t(k)) + "</span>";
}).join("") + "</div>";
var ROW = { words: wordRow, grammar: grammarRow, kanji: kanjiRow };
var COUNT = {
words: "study.wordsCount", grammar: "study.patternsCount",
kanji: "study.kanjiCount"
};
var body = rows.map(ROW[state.kind]).join("");
openRow = null;
var note = state.kind === "grammar"
? '<p class="study-note">' + esc(t("study.grammarNote")) + "</p>" : "";
host.innerHTML =
countLine(rows.length, COUNT[state.kind], true) + note + bar +
'<div class="study-list' + (state.cover ? " is-covered" : "") + '">' +
head + body +
"</div>";
watchMarks();
}
var STATE_CLASS = { k: " is-known", d: " is-learning" };
var markWatcher = null;
function fillMarks(row) {
if (!row || row.querySelector(".study-mark")) return;
var w = row.getAttribute("data-w");
if (w) row.insertAdjacentHTML("beforeend", markButtons(w));
}
function watchMarks() {
if (markWatcher) { markWatcher.disconnect(); markWatcher = null; }
if (state.kind !== "words") return;
var rows = host.querySelectorAll(".study-row[data-w]");
if (!rows.length) return;
if (typeof IntersectionObserver !== "function") {
Array.prototype.forEach.call(rows, fillMarks);
return;
}
markWatcher = new IntersectionObserver(function (entries) {
entries.forEach(function (e) {
if (!e.isIntersecting) return;
fillMarks(e.target);
markWatcher.unobserve(e.target);
});
}, { rootMargin: "800px 0px" });
Array.prototype.forEach.call(rows, function (r) { markWatcher.observe(r); });
}
function fillOnReach(ev) {
var row = ev.target && ev.target.closest
? ev.target.closest(".study-row[data-w]") : null;
if (row) fillMarks(row);
}
function markButtons(w) {
var s = marks[w] || "";
function b(kind, glyph, label) {
return '<button type="button" data-m="' + kind + '" aria-pressed="' +
(s === kind ? "true" : "false") + '" aria-label="' + esc(t(label)) +
'" title="' + esc(t(label)) + '">' + glyph + "</button>";
}
return '<span class="study-mark">' +
b("k", "\u2713", "study.know") + b("d", "\u2717", "study.dontKnow") +
"</span>";
}
function toggleMark(btn) {
var row = btn.closest(".study-row");
var w = row && row.getAttribute("data-w");
if (!w || typeof setKnow !== "function") return;
var want = btn.getAttribute("data-m");
var next = marks[w] === want ? "" : want;
setKnow(state.level, w, next);
if (next) marks[w] = next; else delete marks[w];
row.classList.remove("is-known", "is-learning");
if (next) row.classList.add(STATE_CLASS[next].trim());
row.querySelectorAll(".study-mark button").forEach(function (x) {
x.setAttribute("aria-pressed", x.getAttribute("data-m") === next ? "true" : "false");
});
var old = host.querySelector(".study-marks");
if (old) old.outerHTML = marksBar();
}
function wordRow(row) {
var ne = (I18N.current() === "ne" && row.ne)
? '<em class="study-ne">' + esc(row.ne) + "</em>" : "";
var affix = row.affix
? '<b class="study-affix">' + esc(t("study.affix")) + "</b>" : "";
return '<div class="study-row' + (STATE_CLASS[marks[row.w]] || "") +
'" data-w="' + esc(row.w) + '">' +
'<span class="study-jp">' + esc(row.w) + affix + "</span>" +
'<span class="study-reading' +
(!row.r || row.r === row.w ? " is-echo" : "") + '">' + esc(row.r || "") +
(row.romaji ? '<em>' + esc(row.romaji) + "</em>" : "") + "</span>" +
'<span class="study-en">' + esc(row.en) + ne + "</span>" +
"</div>";
}
function reading(text) {
var dot = text.indexOf(".");
if (dot === -1) return esc(text);
return esc(text.slice(0, dot)) +
'<i class="kanji-okuri">' + esc(text.slice(dot + 1)) + "</i>";
}
function kanjiRow(row) {
var on = row.on.length
? '<b>\u97f3</b> ' + row.on.map(esc).join("\u30fb") : "";
var kun = row.kun.length
? '<b>\u8a13</b> ' + row.kun.map(reading).join("\u30fb") : "";
var ex = row.ex.map(function (e) {
var ne = (I18N.current() === "ne" && e.ne)
? ' <em class="study-ne">' + esc(e.ne) + "</em>" : "";
return '<span class="kanji-ex"><b>' + esc(e.w) + "</b> " +
'<i>' + esc(e.r) + "</i> " + esc(e.en) + ne + "</span>";
}).join("");
return '<div class="study-row is-kanji" data-kanji="' + esc(row.k) + '">' +
'<span class="kanji-cell">' +
'<a class="kanji-char" href="kanji.html?k=' +
encodeURIComponent(row.k) + "&lv=" + state.level.toLowerCase() +
'" aria-expanded="false" title="' + esc(t("study.strokeOrder")) +
'">' + esc(row.k) + "</a>" +
'<span class="kanji-strokes">' + row.s + " " +
esc(t("study.colStrokes")) + "</span>" +
"</span>" +
'<span class="kanji-readings">' + on +
(on && kun ? "<br />" : "") + kun + "</span>" +
'<span class="study-en">' + esc(row.en.join(", ")) +
(ex ? '<span class="kanji-exs">' + ex + "</span>" : "") + "</span>" +
"</div>";
}
var strokeCache = {};
var openRow = null;
function strokesFor(level) {
if (strokeCache[level]) return Promise.resolve(strokeCache[level]);
return fetch(SITE_ROOT + "data/kanji/strokes/" + level.toLowerCase() +
".json", { cache: "no-cache" })
.then(function (r) {
if (!r.ok) throw new Error("HTTP " + r.status);
return r.json();
})
.then(function (d) { strokeCache[level] = d; return d; });
}
function draw(box, paths) {
box.innerHTML =
'<svg viewBox="0 0 109 109" class="kanji-svg" aria-hidden="true">' +
'<g class="kanji-guide">' +
'<line x1="54.5" y1="0" x2="54.5" y2="109" />' +
'<line x1="0" y1="54.5" x2="109" y2="54.5" />' +
"</g>" +
'<g class="kanji-ink">' +
paths.map(function (d) { return '<path d="' + d + '" />'; }).join("") +
"</g>" +
"</svg>";
var delay = 0;
Array.prototype.forEach.call(box.querySelectorAll(".kanji-ink path"),
function (path) {
var len = path.getTotalLength();
var secs = Math.max(0.22, Math.min(0.85, len / 190));
path.style.strokeDasharray = len + " " + len;
path.style.strokeDashoffset = len;
path.style.animation =
"kanji-draw " + secs + "s linear " + delay + "s forwards";
delay += secs + 0.09;
});
}
function steps(paths) {
return paths.map(function (_d, n) {
var upto = paths.slice(0, n + 1).map(function (d, i) {
return '<path d="' + d + '"' + (i === n ? ' class="is-new"' : "") + " />";
}).join("");
return '<li><svg viewBox="0 0 109 109" aria-hidden="true">' +
'<g class="kanji-ink is-static">' + upto + "</g></svg>" +
"<b>" + (n + 1) + "</b></li>";
}).join("");
}
function closeKanji() {
if (!openRow) return;
var link = openRow.querySelector(".kanji-char");
if (link) link.setAttribute("aria-expanded", "false");
openRow.classList.remove("is-open");
var panel = openRow.nextElementSibling;
if (panel && panel.classList.contains("kanji-open")) panel.remove();
openRow = null;
}
function openKanji(rowEl) {
var char = rowEl.dataset.kanji;
var href = rowEl.querySelector(".kanji-char").getAttribute("href");
var wasOpen = rowEl === openRow;
closeKanji();
if (wasOpen) return;
var panel = document.createElement("div");
panel.className = "kanji-open";
panel.innerHTML =
'<div class="kanji-open-inner">' +
'<div class="kanji-open-draw"><div class="spinner"></div></div>' +
'<div class="kanji-open-body">' +
'<h3>' + esc(t("study.strokeOrder")) + "</h3>" +
'<ol class="kanji-open-steps"></ol>' +
'<div class="kanji-open-actions">' +
'<button type="button" class="btn btn-ghost kanji-replay">' +
esc(t("study.replay")) + "</button>" +
'<a class="btn btn-primary" href="' + href + '">' +
esc(char) + ' <span aria-hidden="true">\u2197</span></a>' +
"</div>" +
"</div>" +
'<button type="button" class="kanji-open-close" ' +
'aria-label="&times;">&times;</button>' +
"</div>";
rowEl.parentNode.insertBefore(panel, rowEl.nextSibling);
rowEl.classList.add("is-open");
rowEl.querySelector(".kanji-char").setAttribute("aria-expanded", "true");
openRow = rowEl;
var box = panel.querySelector(".kanji-open-draw");
strokesFor(state.level).then(function (all) {
var paths = all[char];
if (!paths) {
box.innerHTML = '<p class="stats-empty">' +
esc(t("study.strokesMissing")) + "</p>";
return;
}
draw(box, paths);
panel.querySelector(".kanji-open-steps").innerHTML = steps(paths);
panel.querySelector(".kanji-replay").addEventListener("click",
function () { draw(box, paths); });
}).catch(function () {
box.innerHTML = '<p class="stats-empty">' +
esc(t("study.strokesMissing")) + "</p>";
});
}
host.addEventListener("focusin", fillOnReach);
host.addEventListener("click", function (ev) {
fillOnReach(ev);
if (ev.target.closest(".kanji-open-close")) { closeKanji(); return; }
var mark = ev.target.closest(".study-mark button");
if (mark) { toggleMark(mark); return; }
var cover = ev.target.closest(".study-cover");
if (cover) {
state.cover = !state.cover;
saveCover();
applyCover();
return;
}
if (state.cover) {
var cell = ev.target.closest(
".study-reading, .study-en, .study-example, .kanji-readings");
var row = cell && cell.closest(".study-row");
if (row && !row.classList.contains("is-head")) {
row.classList.toggle("is-shown");
return;
}
}
var filter = ev.target.closest(".study-filter");
if (filter) {
state.show = filter.getAttribute("data-show") || "";
render();
return;
}
var link = ev.target.closest(".kanji-char");
if (!link) return;
if (ev.metaKey || ev.ctrlKey || ev.shiftKey || ev.button) return;
ev.preventDefault();
openKanji(link.closest(".study-row"));
});
document.addEventListener("keydown", function (ev) {
if (ev.key === "Escape") closeKanji();
});
function grammarRow(row) {
var ne = (I18N.current() === "ne" && row.ne)
? '<em class="study-ne">' + esc(row.ne) + "</em>" : "";
return '<div class="study-row is-grammar">' +
'<span class="study-jp">' + esc(row.p) + "</span>" +
'<span class="study-en">' + esc(row.en) + ne + "</span>" +
'<span class="study-example"><b>' + esc(row.ja) + "</b>" +
"<em>" + esc(row.ex) + "</em></span>" +
"</div>";
}
function syncHeaderOffset() {
var head = document.querySelector(".site-header");
if (!head) return;
document.documentElement.style.setProperty(
"--header-h", Math.round(head.getBoundingClientRect().height) + "px");
}
syncHeaderOffset();
window.addEventListener("resize", syncHeaderOffset);
document.addEventListener("languagechange", syncHeaderOffset);
var controls = document.querySelector(".study-controls");
function syncControlsOffset() {
if (!controls) return;
document.body.style.setProperty(
"--controls-raw",
Math.round(controls.getBoundingClientRect().height) + "px");
}
syncControlsOffset();
if (controls) document.body.classList.add("has-bar");
window.addEventListener("resize", syncControlsOffset);
document.addEventListener("languagechange", syncControlsOffset);
if (typeof ResizeObserver === "function" && controls) {
new ResizeObserver(syncControlsOffset).observe(controls);
}
function wireStickyControls() {
if (!controls || !window.IntersectionObserver) return;
var mark = document.createElement("div");
mark.setAttribute("aria-hidden", "true");
mark.style.cssText = "height:0;";
controls.parentNode.insertBefore(mark, controls);
var io = null;
var gap = 0;
function wire() {
if (io) io.disconnect();
var header = document.querySelector(".site-header");
var top = header ? header.getBoundingClientRect().height : 0;
if (!controls.classList.contains("is-stuck")) {
gap = controls.getBoundingClientRect().top -
mark.getBoundingClientRect().bottom;
}
io = new IntersectionObserver(function (entries) {
controls.classList.toggle("is-stuck", !entries[0].isIntersecting);
}, { rootMargin: -Math.round(top + Math.max(gap, 0)) + "px 0px 0px 0px" });
io.observe(mark);
}
wire();
window.addEventListener("resize", wire);
document.addEventListener("languagechange", wire);
}
wireStickyControls();
var urlSynced = false;
function syncUrl() {
if (!window.history || !history.replaceState) return;
var here = location.pathname.replace(/[^/]*$/, "");
var url = here + "study.html?lv=" + state.level.toLowerCase() +
"&kind=" + state.kind;
if (/\/study\/[a-z0-9-]+\.html$/.test(location.pathname)) return;
try {
history[urlSynced ? "pushState" : "replaceState"]({
lv: state.level, kind: state.kind
}, "", url);
urlSynced = true;
} catch (e) { }
}
window.addEventListener("popstate", function (ev) {
var st = ev.state;
if (!st || !st.lv) return;
state.level = st.lv;
state.kind = st.kind;
syncTabs();
load();
});
function syncQuizLink() {
var a = document.getElementById("quizLink");
if (!a) return;
var base = (a.getAttribute("href") || "quiz.html").split("?")[0];
a.setAttribute("href", base + "?level=" + state.level + "&kind=" + state.kind);
}
function syncTabs() {
syncQuizLink();
document.querySelectorAll(".study-tab").forEach(function (tab) {
var want = tab.dataset.level
? tab.dataset.level === state.level
: tab.dataset.kind === state.kind;
tab.classList.toggle("is-on", want);
});
}
function returnToListTop() {
if (!host || host.getBoundingClientRect().top >= 0) return;
host.scrollIntoView();
}
document.querySelectorAll(".study-tab").forEach(function (tab) {
tab.addEventListener("click", function () {
var group = tab.parentNode;
if (tab.classList.contains("is-on")) return;
returnToListTop();
group.querySelectorAll(".study-tab").forEach(function (t2) {
t2.classList.toggle("is-on", t2 === tab);
});
if (tab.dataset.level) state.level = tab.dataset.level;
if (tab.dataset.kind) state.kind = tab.dataset.kind;
syncUrl();
syncQuizLink();
load();
});
});
var search = document.getElementById("studySearch");
if (search) {
search.addEventListener("input", function () {
state.query = search.value.trim().toLowerCase();
returnToListTop();
render();
});
}
document.addEventListener("languagechange", function () {
if (cache[key()]) render();
});
syncTabs();
load();
})();